import pytest

from bedrock_protocol import v729, v1001, v2225

# generated by gophertunnel 500a41a:
# protocol.NewWriter(buf, 0).UBlockPos(&protocol.BlockPos{0, -1, 0})
NETWORK_BLOCK_POSITION = bytes.fromhex("00ffffffff0f00")

SLOT_PREFIX = bytes.fromhex("030340120000")

# generated by gophertunnel 6353c49:
# protocol.StackResponseSlotInfo{Slot: 3, HotbarSlot: 3, Count: 64, StackNetworkID: 9, DurabilityCorrection: -32768}
SLOT_MINIMUM = bytes.fromhex("030340120000ffff03")

# generated by gophertunnel 6353c49:
# protocol.StackResponseSlotInfo{Slot: 3, HotbarSlot: 3, Count: 64, StackNetworkID: 9, DurabilityCorrection: 32767}
SLOT_MAXIMUM = bytes.fromhex("030340120000feff03")


@pytest.mark.parametrize(
    ("body", "packet"),
    [
        pytest.param(
            bytes(3) + bytes.fromhex("ffffffff10") + bytes(4), v2225.NetworkChunkPublisherUpdatePacket, id="uvarint32"
        ),
        pytest.param(bytes.fromhex("ffffffffffffffffff02") + bytes(13), v2225.SetActorMotionPacket, id="uvarint64"),
    ],
)
def test_decode_rejects_a_varint_that_overflows_its_type(body, packet):
    with pytest.raises(ValueError, match="at byte"):
        packet.from_bytes(body)


def test_decode_rejects_a_string_length_beyond_the_body():
    with pytest.raises(ValueError, match="at byte"):
        v2225.ServerToClientHandshakePacket.from_bytes(bytes.fromhex("ffffffff0f"))


def test_decode_rejects_nbt_nested_past_the_depth_limit():
    body = bytes(3) + b"\x0a\x00" + b"\x0a\x01a" * 128 + bytes(129)
    with pytest.raises(ValueError, match="at byte"):
        v2225.BlockActorDataPacket.from_bytes(body)


def test_decode_rejects_a_negative_nbt_byte_array_length():
    with pytest.raises(ValueError, match="at byte"):
        v2225.BlockActorDataPacket.from_bytes(bytes(3) + bytes.fromhex("0a000701610100"))


SLOTS = [
    pytest.param(-32768, SLOT_MINIMUM, id="minimum"),
    pytest.param(32767, SLOT_MAXIMUM, id="maximum"),
]


@pytest.mark.parametrize(("durability_correction", "golden"), SLOTS)
def test_an_int16_varint_encodes_at_its_bounds(durability_correction, golden):
    slot = v1001.ItemStackResponseSlotInfo(
        requested_slot=3,
        slot=3,
        amount=64,
        item_stack_net_id=v1001.ItemStackNetId(raw_id=9),
        durability_correction=durability_correction,
    )
    assert bytes(slot) == golden


@pytest.mark.parametrize(("durability_correction", "golden"), SLOTS)
def test_an_int16_varint_decodes_at_its_bounds(durability_correction, golden):
    slot = v1001.ItemStackResponseSlotInfo(
        requested_slot=3,
        slot=3,
        amount=64,
        item_stack_net_id=v1001.ItemStackNetId(raw_id=9),
        durability_correction=durability_correction,
    )
    assert v1001.ItemStackResponseSlotInfo.from_bytes(golden) == slot


@pytest.mark.parametrize("wire", ["808004", "818004"])
def test_decode_rejects_an_int16_varint_beyond_its_bounds(wire):
    with pytest.raises(ValueError, match="at byte"):
        v1001.ItemStackResponseSlotInfo.from_bytes(SLOT_PREFIX + bytes.fromhex(wire))


def test_a_signed_member_of_an_unsigned_varint_encodes_to_its_golden():
    assert bytes(v729.NetworkBlockPosition(x=0, y=-1, z=0)) == NETWORK_BLOCK_POSITION


def test_a_signed_member_of_an_unsigned_varint_decodes_from_its_golden():
    assert v729.NetworkBlockPosition.from_bytes(NETWORK_BLOCK_POSITION) == v729.NetworkBlockPosition(x=0, y=-1, z=0)
